package com.corta.app.ui.contacts

/**
 * Directorio Oficial de Telecomunicaciones y Servicios Esenciales de Chile (~650 registros).
 * Cubre las 16 Regiones de Chile y las 346 Comunas del país.
 */
enum class ChileanRegion(
    val code: String,
    val displayName: String,
    val shortName: String
) {
    ALL("ALL", "Todas las regiones", "Todas"),
    RM("RM", "Región Metropolitana de Santiago", "Metropolitana"),
    V("V", "Región de Valparaíso", "Valparaíso"),
    VIII("VIII", "Región del Biobío", "Biobío"),
    IV("IV", "Región de Coquimbo", "Coquimbo"),
    IX("IX", "Región de La Araucanía", "Araucanía"),
    X("X", "Región de Los Lagos", "Los Lagos"),
    VII("VII", "Región del Maule", "Maule"),
    VI("VI", "Región de O'Higgins", "O'Higgins"),
    II("II", "Región de Antofagasta", "Antofagasta"),
    XVI("XVI", "Región de Ñuble", "Ñuble"),
    I("I", "Región de Tarapacá", "Tarapacá"),
    XIV("XIV", "Región de Los Ríos", "Los Ríos"),
    XV("XV", "Región de Arica y Parinacota", "Arica"),
    III("III", "Región de Atacama", "Atacama"),
    XI("XI", "Región de Aysén", "Aysén"),
    XII("XII", "Región de Magallanes y Antártica", "Magallanes");

    companion object {
        fun fromCode(code: String?): ChileanRegion {
            return entries.firstOrNull { it.code.equals(code, ignoreCase = true) } ?: ALL
        }
    }
}

enum class DirectoryCategory {
    EMERGENCY,
    MUNICIPAL,
    HEALTH_HOSPITAL,
    POLICE_PDI,
    FIRE_DEPARTMENT,
    UTILITIES,
    OFFICIAL_600
}

