        rawList.add(ItemDef("612200000", "Gasco Magallanes Gas Natural", "XII", "Punta Arenas", DirectoryCategory.UTILITIES, "Red gas natural Magallanes"))

        // Transform to final immutable ChileanDirectoryEntry list
        rawList.mapIndexed { index, item ->
            ChileanDirectoryEntry(
                id = "dir_${item.regionCode}_${item.category.name.lowercase()}_$index",
                name = item.name,
                number = item.number,
                regionCode = item.regionCode,
                comuna = item.comuna,
                category = item.category,
                subtitle = "${item.number} · ${item.desc} (${item.comuna})",
                isVerified = true,
                isFavorite = item.isFavorite
            )
        }
    }

    /**
     * Retorna todos los registros del directorio (~650 registros oficiales de Chile).
     */
    fun getAllEntries(): List<ChileanDirectoryEntry> = entries

    /**
     * Retorna el directorio filtrado por la región seleccionada por el usuario.
     * Si region == ALL, retorna todos los registros.
     * Si se selecciona una región específica, retorna las emergencias y servicios nacionales
     * MÁS todos los registros de esa región.
     */
    fun getEntriesForRegion(region: ChileanRegion): List<ChileanDirectoryEntry> {
        return if (region == ChileanRegion.ALL) {
            entries
        } else {
            entries.filter { it.regionCode == "ALL" || it.regionCode == region.code }
        }
    }

    /**
     * Retorna los registros filtrados por Región y Comuna del usuario.
     * Si comuna != null, las entradas de dicha comuna se ordenan al principio (priorizadas),
     * para que el usuario siempre vea su seguridad municipal, comisaría y hospital local primero.
     */
    fun getEntriesForRegionAndComuna(region: ChileanRegion, comuna: String? = null): List<ChileanDirectoryEntry> {
        val regionEntries = getEntriesForRegion(region)
        if (comuna.isNullOrBlank() || comuna.equals("ALL", ignoreCase = true) || comuna.equals("Todas", ignoreCase = true)) {
            return regionEntries
        }
        val trimmed = comuna.trim()
        val (matchingComuna, others) = regionEntries.partition {
            it.comuna.equals(trimmed, ignoreCase = true)
        }
        return matchingComuna + others
    }

    /**
     * Lista de nombres de comunas disponibles para una región específica.
     */
    fun getComunasForRegion(region: ChileanRegion): List<String> {
        val list = if (region == ChileanRegion.ALL) {
            entries.filter { it.regionCode != "ALL" }.map { it.comuna }.distinct().sorted()
        } else {
            entries.filter { it.regionCode == region.code }.map { it.comuna }.distinct().sorted()
        }
        return list
    }

    /**
     * Lista de todas las comunas con su región correspondiente para el buscador.
     */
    fun getAllComunasWithRegion(): List<Pair<String, ChileanRegion>> {
        return entries
            .filter { it.regionCode != "ALL" && it.category == DirectoryCategory.MUNICIPAL }
            .map { Pair(it.comuna, ChileanRegion.fromCode(it.regionCode)) }
            .distinctBy { it.first }
            .sortedBy { it.first }
    }
}
